css_variables:
:root {
  --color-primary: #0A5B6E;
  --color-secondary: #1E6F8C;
  --color-accent: #0EA5E9;
  --color-highlight: #E9F7FB;
  --color-bg: #FFFFFF;
  --color-text: #0B1220;
  --color-text-muted: #64748B;
  --color-border: #E2E8F0;
  --font-heading: 'Sora', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-body: 'IBM Plex Sans', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-size-display: 56px;
  --font-size-h1: 40px;
  --font-size-h2: 30px;
  --font-size-h3: 24px;
  --font-size-h4: 18px;
  --font-size-body: 16px;
  --font-size-small: 13px;
  --font-weight-heading: 700;
  --font-weight-body: 400;
  --line-height-body: 1.7;
  --border-radius: 10px;
  --shadow-card: 0 2px 8px rgba(0,0,0,0.08), 0 8px 24px rgba(0,0,0,0.06);
}
